import sys
import logging
import inspect
import traceback
from .stack import Stack
from . import logger as core_logger


class NoException(Exception):
    """Dummy exception to pass siently."""
    pass  # pylint: disable=unnecessary-pass


class NoActiveScope(Exception):
    """Scopes stack is empty, there is no current scope."""
    def __init__(self):
        """Basic initialization."""
        super(NoActiveScope, self).__init__("Scopes stack is empty, there is no current scope!")


class UnknownScopeOwner(Exception):
    """Scopes owner is unknown, don't know which scopes stack to select."""
    def __init__(self):
        """Basic initialization."""
        super(UnknownScopeOwner, self).__init__("Scopes owner is unknown, don't know which scopes stack to select!")


class ResourceReleaserFailed(Exception):
    """Errors cought inside releasing Scope's resources."""
    def __init__(self, exception, releaser, resource, traceback):
        """
        Basic initialization.

        :param exception:
        :param releaser:
        :param resource:
        :param traceback:
        """
        super(ResourceReleaserFailed, self).__init__("Errors cought inside releasing Scope's resources:")
        self.failures = [{'exception': exception, 'releaser': releaser, 'resource': resource, 'traceback': traceback}]

    def append(self, exception, releaser, resource, traceback):
        """Append info about next exception collected by ResourceReleaserFailed container"""
        self.failures.append({'exception': exception, 'releaser': releaser, 'resource': resource, 'traceback': traceback})

    def __str__(self):
        lines = []
        line = super(ResourceReleaserFailed, self).__str__()
        lines.append(line)
        for fail in self.failures:
            line = " {}({}), exception: {}({})".format(fail['releaser'].__name__, fail['resource'],
                                                       fail['exception'].__class__.__name__, fail['exception'])
            lines.append(line)
            line = "  releaser: {}, resource: {}".format(fail['releaser'], fail['resource'])
            lines.append(line)
            trace = traceback.format_tb(fail['traceback'])
            lines.append("\n".join(trace))
        return '\n'.join(lines)


class Scope:
    """Handling of scopes."""
    def __init__(self, name):
        """Basic initialization."""
        self.name = name
        self._used_resources = []
        self.logger = logging.getLogger('al.scopes')

    def __repr__(self):
        return f"Scope(name={self.name})"

    def uses(self, resource, resource_releaser):
        """
        Register usage of resource in given scope together with resource-releaser-function

        :param resource: resource used inside scope
        :param resource_releaser: function that can perform releasing of resource

        :return: None
        """
        # Takes code location of caller of this function
        (_, pathname, lineno, func_name, _, _) = inspect.stack(0)[1]
        call_msg = f"{self!r}.uses({resource})  called by {func_name}() [{pathname}:{lineno}]"
        self.logger.log(level=core_logger.TRACE, msg=call_msg)
        release_data = (resource, resource_releaser)
        self._used_resources.append(release_data)
        self.logger.info(f"{self!r} uses {resource} resource")

    def release_resource(self, resource):
        """
        Release single resources used in given scope

        :return: None
        """
        (_, pathname, lineno, func_name, _, _) = inspect.stack(0)[1]
        call_msg = f"{self!r}.release_resource({resource})  called by {func_name}() [{pathname}:{lineno}]"
        self.logger.log(level=core_logger.TRACE, msg=call_msg)
        for index, (stored_resource, _) in enumerate(reversed(self._used_resources)):
            if stored_resource == resource:
                stored_at_index = len(self._used_resources) - 1 - index
                break
        else:
            self.logger.warning(f"{self!r} resource {resource} not found")
            return  # resource not found
        (resource, resource_releaser) = self._used_resources.pop(stored_at_index)
        self.logger.debug(f"{self!r} releasing {resource} via: {resource_releaser}")
        resource_releaser(resource)
        self.logger.info(f"{self!r} released {resource} resource")

    def release_all_resources(self):
        """
        Release all resources used in given scope

        :return: None
        """
        self.logger.debug(f"{self!r} releasing all resources")
        releasers_exceptions = NoException()  # to make Lint happy
        while self._used_resources:
            (resource, resource_releaser) = self._used_resources.pop()
            try:
                self.logger.debug(f"{self!r} releasing {resource} via: {resource_releaser}")
                resource_releaser(resource)
                self.logger.info(f"{self!r} released {resource}")
            except Exception as exc:  # pylint: disable=broad-except
                _, _, traceback_ = sys.exc_info()
                if isinstance(releasers_exceptions, NoException):
                    releasers_exceptions = ResourceReleaserFailed(exception=exc,
                                                                  releaser=resource_releaser,
                                                                  resource=resource,
                                                                  traceback=traceback_)
                else:
                    releasers_exceptions.append(exception=exc, releaser=resource_releaser,
                                                resource=resource, traceback=traceback_)
        if not isinstance(releasers_exceptions, NoException):
            self.logger.error(f"ResourceReleaserFailed({releasers_exceptions})")
            raise releasers_exceptions


__current_owner = None
__current_scopes = {}  # owner: Stack-of-scopes


def current_scope():
    """Return current/active scope."""
    logger = logging.getLogger('al.scopes')
    (_, pathname, lineno, func_name, _, _) = inspect.stack(0)[1]
    call_msg = f"scope.current_scope()  called by {func_name}() [{pathname}:{lineno}]"
    logger.log(level=core_logger.TRACE, msg=call_msg)
    if __current_scopes == {}:
        logger.error("NoActiveScope")
        raise NoActiveScope()
    if __current_owner is None:
        logger.error("UnknownScopeOwner")
        raise UnknownScopeOwner()
    if __current_scopes[__current_owner].is_empty():
        logger.error("NoActiveScope")
        raise NoActiveScope()
    current = __current_scopes[__current_owner].top()
    logger.debug(f"scope.current_scope() is {current}, owner {__current_owner}")
    return current


def notify_scope_owner_changed(owner):
    """Notify scope which one is current scope owner. This will select scopes stact for that owner."""
    logger = logging.getLogger('al.scopes')
    (_, pathname, lineno, func_name, _, _) = inspect.stack(0)[1]
    call_msg = f"scope.notify_scope_owner_changed({owner})  called by {func_name}() [{pathname}:{lineno}]"
    logger.log(level=core_logger.TRACE, msg=call_msg)
    _notify_scope_owner_changed(owner)


def _notify_scope_owner_changed(owner):
    logger = logging.getLogger('al.scopes')
    global __current_owner  # pylint: disable=global-statement
    if __current_scopes == {}:
        logger.error("NoActiveScope")
        raise NoActiveScope()
    if owner not in __current_scopes:
        logger.error(f"UnknownScopeOwner {owner}")
        raise UnknownScopeOwner()
    if __current_owner != owner:
        __current_owner = owner
        logger.debug(f"switched to scopes stack of {owner}")


def start_new_scope(name, owner):
    """Create new scope and put it on scopes stack per given owner."""
    logger = logging.getLogger('al.scopes')
    if owner not in __current_scopes:
        __current_scopes[owner] = Stack()
    new_scope = Scope(name)
    __current_scopes[owner].push(new_scope)
    logger.debug(f"scope start: {new_scope}, owner {owner} has {__current_scopes[owner].size()} scopes")
    _notify_scope_owner_changed(owner)


def end_current_scope(owner):
    """Finalize last stacked scope and release all resources used inside that scope."""
    logger = logging.getLogger('al.scopes')
    _notify_scope_owner_changed(owner)
    current = current_scope()
    logger.debug(f"     ending: {current}, owner {owner}")
    current.release_all_resources()
    __current_scopes[owner].pop()
    logger.debug(f"scope   end: {current}, owner {owner} has {__current_scopes[owner].size()} scopes")


def shutdown():
    """Forced cleanup of all stacked scopes."""
    logger = logging.getLogger('al.scopes')
    logger.debug("shutting down all scopes")
    global __current_scopes  # pylint: disable=global-statement
    global __current_owner  # pylint: disable=global-statement
    for owner in __current_scopes:
        while not __current_scopes[owner].is_empty():
            __current_scopes[owner].pop().release_all_resources()
    __current_scopes = {}
    __current_owner = None
    logger.debug("all scopes are down")
